import{_ as n,C as o,c as a,o as s,j as e,G as r,a8 as l,a as g}from"./chunks/framework.8HQ-OgOa.js";const S=JSON.parse('{"title":"Settings Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/settings.md","filePath":"en/guide/settings.md"}'),h={name:"en/guide/settings.md"};function d(c,t,u,p,b,f){const i=o("ArticleMetadata");return s(),a("div",null,[t[0]||(t[0]=e("h1",{id:"settings-guide",tabindex:"-1"},[g("Settings Guide "),e("a",{class:"header-anchor",href:"#settings-guide","aria-label":'Permalink to "Settings Guide"'},"​")],-1)),r(i),t[1]||(t[1]=l('<p>ICC-CE offers a wide range of configuration options to suit different user needs. This guide will help you understand the functionality of each setting and find the optimal configuration.</p><h2 id="accessing-settings" tabindex="-1">Accessing Settings <a class="header-anchor" href="#accessing-settings" aria-label="Permalink to &quot;Accessing Settings&quot;">​</a></h2><p>Click the settings icon ⚙️ on the floating toolbar to open the settings panel.</p><h2 id="general-settings" tabindex="-1">General Settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General Settings&quot;">​</a></h2><h3 id="startup-options" tabindex="-1">Startup Options <a class="header-anchor" href="#startup-options" aria-label="Permalink to &quot;Startup Options&quot;">​</a></h3><ul><li><strong>Run at startup</strong>: Set whether the application starts automatically with Windows.</li><li><strong>Dock to sidebar after startup</strong>: Automatically minimize the toolbar to the side of the screen upon launching.</li><li><strong>PowerPoint Support</strong>: Enable PowerPoint integration features.</li></ul><h3 id="auto-update" tabindex="-1">Auto Update <a class="header-anchor" href="#auto-update" aria-label="Permalink to &quot;Auto Update&quot;">​</a></h3><ul><li><strong>Smart update</strong>: Enable the software to automatically check for updates.</li><li><strong>Silent update</strong>: Automatically apply updates in the background during a specified idle period.</li><li><strong>Time period</strong>: Set the hours during which automatic updates are permitted.</li></ul><h2 id="canvas-settings" tabindex="-1">Canvas Settings <a class="header-anchor" href="#canvas-settings" aria-label="Permalink to &quot;Canvas Settings&quot;">​</a></h2><h3 id="pen-settings" tabindex="-1">Pen Settings <a class="header-anchor" href="#pen-settings" aria-label="Permalink to &quot;Pen Settings&quot;">​</a></h3><ul><li><strong>Pen width</strong>: Adjust the thickness of the pen (2-30 pixels).</li><li><strong>Highlighter width</strong>: Adjust the thickness of the highlighter.</li><li><strong>Pen style</strong>: Choose between different writing styles: <ul><li>Standard style: Uniform line thickness.</li><li>Calligraphy style: Line thickness varies depending on the drawing direction.</li></ul></li></ul><h3 id="eraser-settings" tabindex="-1">Eraser Settings <a class="header-anchor" href="#eraser-settings" aria-label="Permalink to &quot;Eraser Settings&quot;">​</a></h3><ul><li><strong>Eraser size</strong>: Choose between Small, Medium, Large, and Extra Large.</li><li><strong>Eraser shape</strong>: Circle or Rectangle.</li></ul><h3 id="touch-input" tabindex="-1">Touch Input <a class="header-anchor" href="#touch-input" aria-label="Permalink to &quot;Touch Input&quot;">​</a></h3><ul><li><strong>Show cursor</strong>: Display the cursor position while drawing.</li><li><strong>Touch pressure mode</strong>: Simulate pressure sensitivity for touch screens.</li><li><strong>Disable pressure sensitivity</strong>: Use a uniform thickness for all strokes.</li><li><strong>Nib mode</strong>: Optimize inputs specifically for styluses/active pens.</li></ul><h3 id="line-straightening" tabindex="-1">Line Straightening <a class="header-anchor" href="#line-straightening" aria-label="Permalink to &quot;Line Straightening&quot;">​</a></h3><ul><li><strong>Auto-straighten straight lines</strong>: Enable/disable automatic line correction.</li><li><strong>Length threshold</strong>: Set the minimum line length to trigger correction.</li><li><strong>Sensitivity</strong>: Control the straightening algorithm threshold (0.05-2.0): <ul><li>Low values (0.05-0.3): Requires the hand-drawn line to be very close to a straight line.</li><li>Medium values (0.3-1.0): Suitable for general use.</li><li>High values (1.0-2.0): More relaxed correction standard.</li></ul></li></ul><h3 id="endpoint-snapping" tabindex="-1">Endpoint Snapping <a class="header-anchor" href="#endpoint-snapping" aria-label="Permalink to &quot;Endpoint Snapping&quot;">​</a></h3><ul><li><strong>Straight line endpoint snapping</strong>: Enable/disable snapping for line ends.</li><li><strong>Snapping distance</strong>: Set the radius for endpoint snapping (5-50 pixels).</li></ul><h2 id="shape-recognition" tabindex="-1">Shape Recognition <a class="header-anchor" href="#shape-recognition" aria-label="Permalink to &quot;Shape Recognition&quot;">​</a></h2><ul><li><strong>Enable shape recognition</strong>: Turn on automatic shape recognition.</li><li><strong>Recognize rectangle</strong>: Recognize and optimize drawn rectangles and squares.</li><li><strong>Recognize triangle</strong>: Recognize and optimize drawn triangles.</li><li><strong>Recognize circle</strong>: Recognize and optimize drawn circles and ellipses.</li><li><strong>Rectangle pressure</strong>: Apply pressure sensitivity effects inside recognized rectangles.</li><li><strong>Triangle pressure</strong>: Apply pressure sensitivity effects inside recognized triangles.</li></ul><h2 id="personalization" tabindex="-1">Personalization <a class="header-anchor" href="#personalization" aria-label="Permalink to &quot;Personalization&quot;">​</a></h2><h3 id="toolbar-settings" tabindex="-1">Toolbar Settings <a class="header-anchor" href="#toolbar-settings" aria-label="Permalink to &quot;Toolbar Settings&quot;">​</a></h3><ul><li><strong>Floating toolbar icons</strong>: Select different icon styles.</li><li><strong>Toolbar scale</strong>: Adjust the size of the toolbar (0.5x to 1.25x).</li><li><strong>Toolbar opacity</strong>: Adjust the transparency of the toolbar (0.3 to 1.0).</li><li><strong>PPT mode opacity</strong>: Specific toolbar transparency when PowerPoint is active.</li></ul><h3 id="interface-options" tabindex="-1">Interface Options <a class="header-anchor" href="#interface-options" aria-label="Permalink to &quot;Interface Options&quot;">​</a></h3><ul><li><strong>Show nib mode button</strong>: Toggle the visibility of the nib mode switch in the color palette.</li><li><strong>Whiteboard UI scale</strong>: Enable 80% UI scaling under whiteboard mode.</li><li><strong>Show date and time</strong>: Show the current time in whiteboard mode.</li><li><strong>Quick panel</strong>: Enable the quick panel when the toolbar is docked.</li><li><strong>Dock button icon</strong>: Choose between arrow or pen-shaped dock icons.</li></ul><h2 id="advanced-settings" tabindex="-1">Advanced Settings <a class="header-anchor" href="#advanced-settings" aria-label="Permalink to &quot;Advanced Settings&quot;">​</a></h2><h3 id="touch-settings" tabindex="-1">Touch Settings <a class="header-anchor" href="#touch-settings" aria-label="Permalink to &quot;Touch Settings&quot;">​</a></h3><ul><li><strong>Touch multiplier</strong>: Fine-tune touch sensitivity.</li><li><strong>Nib mode border width</strong>: Set the boundary width for stylus detection.</li><li><strong>Finger mode border width</strong>: Set the boundary width for finger touch detection.</li></ul><h3 id="system-integration" tabindex="-1">System Integration <a class="header-anchor" href="#system-integration" aria-label="Permalink to &quot;System Integration&quot;">​</a></h3><ul><li><strong>Full screen helper</strong>: Improve drawing experiences in full-screen applications.</li><li><strong>Edge gestures</strong>: Enable or disable Windows edge gestures.</li><li><strong>Force full screen</strong>: Run the application in forced full-screen mode.</li><li><strong>DPI change detection</strong>: Detect and adapt to display DPI changes.</li><li><strong>Resolution change detection</strong>: Monitor and adapt to screen resolution changes.</li></ul><h3 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h3><ul><li><strong>Enable logging</strong>: Record application activity logs for troubleshooting.</li><li><strong>Confirm close</strong>: Show a confirmation dialog when exiting the application.</li></ul><h2 id="automation-settings" tabindex="-1">Automation Settings <a class="header-anchor" href="#automation-settings" aria-label="Permalink to &quot;Automation Settings&quot;">​</a></h2><h3 id="software-detection" tabindex="-1">Software Detection <a class="header-anchor" href="#software-detection" aria-label="Permalink to &quot;Software Detection&quot;">​</a></h3><p>Enable automatic detection of specific software to optimize ICC-CE behavior:</p><ul><li>EasiNote, EasiCamera</li><li>Various whiteboard software (Seewo, Haixin, Nano, etc.)</li><li>PowerPoint Slideshows</li><li>Microsoft Whiteboard</li><li>Other common educational software</li></ul><h3 id="auto-save" tabindex="-1">Auto Save <a class="header-anchor" href="#auto-save" aria-label="Permalink to &quot;Auto Save&quot;">​</a></h3><ul><li><strong>Screenshot save location</strong>: Set the storage path for screenshots.</li><li><strong>Date folders</strong>: Organize saved files inside folders named by date.</li><li><strong>Save ink on screenshot</strong>: Save raw ink strokes along with the screenshot.</li><li><strong>Save ink on clear</strong>: Save canvas content before clearing it.</li><li><strong>Auto delete files</strong>: Automatically clean up historical files.</li><li><strong>Retention days</strong>: Set the maximum lifetime for auto-saved files.</li></ul><h2 id="powerpoint-settings" tabindex="-1">PowerPoint Settings <a class="header-anchor" href="#powerpoint-settings" aria-label="Permalink to &quot;PowerPoint Settings&quot;">​</a></h2><h3 id="button-settings" tabindex="-1">Button Settings <a class="header-anchor" href="#button-settings" aria-label="Permalink to &quot;Button Settings&quot;">​</a></h3><ul><li><strong>Show PPT buttons</strong>: Display control buttons in slideshow mode.</li><li><strong>Page numbers clickable</strong>: Allow switching slides by clicking page numbers.</li><li><strong>Button position</strong>: Adjust the position of the buttons on the left or right side.</li><li><strong>Button style</strong>: Customize button transparency, background, and display options.</li></ul><h3 id="behavior-settings" tabindex="-1">Behavior Settings <a class="header-anchor" href="#behavior-settings" aria-label="Permalink to &quot;Behavior Settings&quot;">​</a></h3><ul><li><strong>Show canvas on new slide</strong>: Automatically display the canvas when switching slides.</li><li><strong>Save slide ink</strong>: Automatically save annotations drawn on slides.</li><li><strong>Page notification</strong>: Display notifications when changing slides.</li><li><strong>Gesture control</strong>: Enable gesture controls during slideshows.</li></ul>',44))])}const w=n(h,[["render",d]]);export{S as __pageData,w as default};
